/** Every notification the web remote hears, and its params. */
export interface Notifications {
  "agent/changed": Agent;
  "agent/elicitation": ElicitationNotification;
  "agent/entry": EntryNotification;
  "agent/permission": PermissionNotification;
  "agent/removed": AgentRemovedNotification;
  "agent/showFile": ShowFileNotification;
  "agents/draftOptions": DraftOptionsNotification;
  "attention/changed": AttentionNotification;
  "clone/changed": CloneNotification;
  "control/hostChanged": JSONValue;
  "files/changed": FilesChangedNotification;
  "leases/changed": LeaseSnapshot;
  "modes/changed": Record<string, JSONValue>;
  "project/changed": ProjectSummary;
  "storage/writeFailed": WriteFailure;
  "workflow/changed": WorkflowSummary;
  "workflow/removed": WorkflowRemovedNotification;
}

/** Each interface's keys, for checking Swift-encoded fixtures against these types. */
